insert into public.questions (exam_category, subject, topic, type, difficulty, body, body_hi, question_data, options, marks_correct, marks_wrong, explanation, explanation_hi, concept_group_id, source_type, source_citation, status)
values
('upsc','History','Medieval','mcq','easy','When Minhaj-i Siraj, a chronicler of the thirteenth century, used the term ''Hindustan'', he meant','जब तेरहवीं सदी के इतिहासकार मिन्हाज-ए-सिराज ने ''हिंदुस्तान'' शब्द का प्रयोग किया, तो उनका आशय था','{"craft": "inference"}'::jsonb,'[{"id": "a", "body": "Punjab, Haryana and the Ganga-Yamuna lands under the Delhi Sultan", "body_hi": "दिल्ली के सुल्तान के अधीन पंजाब, हरियाणा और गंगा-यमुना के बीच की भूमि", "isCorrect": true}, {"id": "b", "body": "the whole of the subcontinent, from Kashmir to the southern tip of the peninsula", "body_hi": "कश्मीर से प्रायद्वीप के दक्षिणी छोर तक पूरा उपमहाद्वीप", "isCorrect": false}, {"id": "c", "body": "only the Deccan plateau, which lay beyond the reach of the Delhi Sultans", "body_hi": "केवल दक्कन का पठार, जो दिल्ली के सुल्तानों की पहुँच से बाहर था", "isCorrect": false}, {"id": "d", "body": "the lands lying to the west of the Indus, from which the Turks had come", "body_hi": "सिंधु के पश्चिम की भूमि, जहाँ से तुर्क आए थे", "isCorrect": false}]'::jsonb,2,0.66,'Minhaj used Hindustan in a political sense, for the lands that were part of the dominions of the Delhi Sultan -- Punjab, Haryana and the lands between the Ganga and the Yamuna; he never included south India in it. In the early sixteenth century Babur used Hindustan to describe the geography, the fauna and the culture of the inhabitants of the subcontinent -- closer to, though not the same as, the modern idea of ''India''. Historians therefore read such terms in the sense their writers gave them.','मिन्हाज ने हिंदुस्तान का प्रयोग राजनीतिक अर्थ में, दिल्ली के सुल्तान के अधिकार-क्षेत्र वाली भूमि के लिए किया -- पंजाब, हरियाणा और गंगा-यमुना के बीच की भूमि; उन्होंने दक्षिण भारत को इसमें कभी शामिल नहीं किया। सोलहवीं सदी के आरंभ में बाबर ने हिंदुस्तान का प्रयोग उपमहाद्वीप के भूगोल, जीव-जंतुओं और निवासियों की संस्कृति के वर्णन के लिए किया -- जो ''भारत'' के आधुनिक विचार के निकट है, पर उसके समान नहीं। इसलिए इतिहासकार ऐसे शब्दों को उसी अर्थ में पढ़ते हैं जो उनके लेखकों ने दिया।','l1-his-hindustan-minhaj-meaning','original_pattern_matched','NCERT Class VII, History -- Our Pasts II, Chapter 1 (Tracing Changes through a Thousand Years).','draft'),
('upsc','History','Medieval','mcq','easy','In medieval times, the word ''foreigner'' (pardesi in Hindi, ajnabi in Persian) was generally used for','मध्यकाल में ''विदेशी'' शब्द (हिंदी में परदेसी, फ़ारसी में अजनबी) प्रायः किसके लिए प्रयुक्त होता था?','{"craft": "inference"}'::jsonb,'[{"id": "a", "body": "only those people who had come from lands beyond the subcontinent''s frontiers", "body_hi": "केवल वे लोग जो उपमहाद्वीप की सीमाओं के पार की भूमि से आए हों", "isCorrect": false}, {"id": "b", "body": "only European traders who had settled in the port towns", "body_hi": "केवल बंदरगाह नगरों में बसे यूरोपीय व्यापारी", "isCorrect": false}, {"id": "c", "body": "only people who followed a different religion from the ruler", "body_hi": "केवल वे लोग जो शासक से भिन्न धर्म मानते हों", "isCorrect": false}, {"id": "d", "body": "any stranger who was not part of a particular society or culture", "body_hi": "कोई भी अजनबी जो किसी विशेष समाज या संस्कृति का भाग न हो", "isCorrect": true}]'::jsonb,2,0.66,'A foreigner was any stranger who appeared, say, in a village -- someone who was not part of that society or culture. A city-dweller might regard a forest-dweller as a foreigner, while two peasants of the same village were not foreigners to each other even if they had different religious or caste backgrounds. Today the word means someone who is not an Indian -- a reminder that the meanings of words change over time.','विदेशी कोई भी ऐसा अजनबी था जो, मान लीजिए, किसी गाँव में आ जाए -- ऐसा व्यक्ति जो उस समाज या संस्कृति का भाग न हो। नगरवासी किसी वनवासी को विदेशी मान सकता था, जबकि एक ही गाँव के दो किसान भिन्न धर्म या जाति के होते हुए भी एक-दूसरे के लिए विदेशी नहीं थे। आज इस शब्द का अर्थ है ऐसा व्यक्ति जो भारतीय नहीं है -- यह याद दिलाता है कि शब्दों के अर्थ समय के साथ बदलते हैं।','l1-his-foreigner-medieval-meaning','original_pattern_matched','NCERT Class VII, History -- Our Pasts II, Chapter 1 (Tracing Changes through a Thousand Years).','draft'),
('upsc','History','Medieval','statement_based','easy','Consider the following statements about maps of the subcontinent made in the medieval period:','मध्यकाल में बने उपमहाद्वीप के मानचित्रों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["In the map made by the Arab geographer al-Idrisi in 1154, south India appears where one would expect to find north India.", "Maps of this period followed the same conventions as modern maps, so they can be read in the same way."], "statements_hi": ["अरब भूगोलवेत्ता अल-इदरीसी द्वारा 1154 में बनाए गए मानचित्र में दक्षिण भारत वहाँ दिखता है जहाँ उत्तर भारत होने की अपेक्षा होती है।", "इस काल के मानचित्र आधुनिक मानचित्रों की ही परिपाटियों पर बने थे, इसलिए उन्हें उसी तरह पढ़ा जा सकता है।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "inference"}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": true}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct. Al-Idrisi''s map, a section of a larger map of the world, shows the subcontinent upside down by modern standards, with Sri Lanka at the top. Statement 2 is wrong: the science of cartography changed considerably. A French map made in 1720, nearly 600 years later, looks far more familiar because more information had become available and the conventions had changed -- so historians read old maps within their own contexts.','केवल कथन 1 सही है। विश्व के एक बड़े मानचित्र का भाग, अल-इदरीसी का मानचित्र, आधुनिक मानकों के अनुसार उपमहाद्वीप को उल्टा दिखाता है, जिसमें श्रीलंका ऊपर है। कथन 2 गलत है: मानचित्र-विज्ञान में काफ़ी परिवर्तन हुए। लगभग 600 वर्ष बाद, 1720 में बना एक फ़्रांसीसी मानचित्र कहीं अधिक परिचित लगता है, क्योंकि अधिक जानकारी उपलब्ध हो गई थी और परिपाटियाँ बदल गई थीं -- इसलिए इतिहासकार पुराने मानचित्रों को उनके अपने संदर्भ में पढ़ते हैं।','l1-his-al-idrisi-map-1154','original_pattern_matched','NCERT Class VII, History -- Our Pasts II, Chapter 1 (Tracing Changes through a Thousand Years).','draft'),
('upsc','History','Medieval','statement_based','easy','Consider the following statements about the new dynasties of the seventh to twelfth centuries:','सातवीं से बारहवीं सदी के नए राजवंशों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The Rashtrakuta chief Dantidurga performed a ritual called hiranya-garbha (''the golden womb''), believed to lead to his ''rebirth'' as a kshatriya.", "Kadamba Mayurasharman and the Gurjara-Pratihara Harichandra were kshatriyas by birth, who took up arms in keeping with their tradition.", "Samantas, the subordinate chiefs of the period, were never able to declare themselves independent."], "statements_hi": ["राष्ट्रकूट सरदार दंतिदुर्ग ने हिरण्यगर्भ (''सोने का गर्भ'') नामक अनुष्ठान किया, जिससे माना जाता था कि वह क्षत्रिय के रूप में ''पुनर्जन्म'' लेता है।", "कदंब मयूरशर्मन और गुर्जर-प्रतिहार हरिचंद्र जन्म से क्षत्रिय थे, जिन्होंने अपनी परंपरा के अनुसार शस्त्र उठाए।", "इस काल के अधीनस्थ सरदार, सामंत, स्वयं को कभी स्वतंत्र घोषित नहीं कर पाए।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct: in the mid-eighth century Dantidurga, who overthrew his Chalukya overlord, performed the hiranya-garbha with the help of brahmanas -- a ritual thought to make the performer a kshatriya even if he was not one by birth. Statement 2 is wrong: Mayurasharman and Harichandra were brahmanas who gave up their traditional professions, took to arms and set up kingdoms in Karnataka and Rajasthan respectively. Statement 3 is wrong: as samantas gained power and wealth they declared themselves maha-samanta or maha-mandaleshvara (great lord of a ''circle'' or region), and some asserted their independence -- as the Rashtrakutas did against the Chalukyas.','केवल कथन 1 सही है: आठवीं सदी के मध्य में अपने चालुक्य अधिपति को उखाड़ फेंकने वाले दंतिदुर्ग ने ब्राह्मणों की सहायता से हिरण्यगर्भ अनुष्ठान किया -- माना जाता था कि यह अनुष्ठान करने वाले को क्षत्रिय बना देता है, भले ही वह जन्म से क्षत्रिय न हो। कथन 2 गलत है: मयूरशर्मन और हरिचंद्र ब्राह्मण थे, जिन्होंने अपने परंपरागत व्यवसाय छोड़कर शस्त्र उठाए और क्रमशः कर्नाटक और राजस्थान में राज्य स्थापित किए। कथन 3 गलत है: शक्ति और धन बढ़ने पर सामंतों ने स्वयं को महासामंत या महामंडलेश्वर (किसी ''मंडल'' या क्षेत्र का महान स्वामी) घोषित किया, और कुछ ने अपनी स्वतंत्रता जताई -- जैसे राष्ट्रकूटों ने चालुक्यों के विरुद्ध किया।','l1-his-hiranyagarbha-new-dynasties','original_pattern_matched','NCERT Class VII, History -- Our Pasts II, Chapter 2 (New Kings and Kingdoms).','draft'),
('upsc','History','Medieval','statement_based','easy','Consider the following statements about Thanjavur in the Chola period:','चोल काल में तंजावुर के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The architect of the Rajarajeshvara temple, Kunjaramallan Rajaraja Perunthachchan, had his name carved on the temple wall.", "Bronze images were made by the craftspersons of Svamimalai, near Thanjavur.", "Saliya weavers of Thanjavur and nearby Uraiyur produced cloth for temple festivals, the court and the people."], "statements_hi": ["राजराजेश्वर मंदिर के वास्तुकार कुंजरमल्लन राजराज पेरुन्तच्चन ने अपना नाम मंदिर की दीवार पर उकेरवाया।", "काँसे की प्रतिमाएँ तंजावुर के निकट स्वामीमलै के शिल्पकार बनाते थे।", "तंजावुर और निकट के उरैयूर के सालिया बुनकर मंदिर के उत्सवों, दरबार और जनता के लिए कपड़ा बनाते थे।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. Thanjavur, the Chola capital, was both a temple town and a centre of crafts: Perunthachchan''s name on the wall of the Rajarajeshvara temple records its architect; the sthapatis of Svamimalai cast the bronze images; and the Saliya weavers made flags for temple festivals, fine cotton for the king and nobles, and coarser cloth for the people. Temples were often the hub of a town''s economy -- they employed craftspersons and others, held land, and received gifts from rulers and merchants.','तीनों कथन सही हैं। चोल राजधानी तंजावुर एक मंदिर-नगर भी था और शिल्पों का केंद्र भी: राजराजेश्वर मंदिर की दीवार पर पेरुन्तच्चन का नाम उसके वास्तुकार को दर्ज करता है; स्वामीमलै के स्थपति काँसे की प्रतिमाएँ ढालते थे; और सालिया बुनकर मंदिर के उत्सवों के लिए ध्वज, राजा और अमीरों के लिए बारीक सूती कपड़ा, और जनता के लिए मोटा कपड़ा बनाते थे। मंदिर प्रायः नगर की अर्थव्यवस्था का केंद्र होते थे -- वे शिल्पकारों और अन्य लोगों को काम देते थे, भूमि रखते थे, और शासकों तथा व्यापारियों से दान पाते थे।','l1-his-thanjavur-temple-town','original_pattern_matched','NCERT Class VII, History -- Our Pasts II, Chapter 6 (Towns, Traders and Craftspersons).','draft'),
('upsc','History','Medieval','match_the_following','easy','Consider the following pairs of communities and the regions in which they were influential in the medieval period:','समुदायों और उन क्षेत्रों के निम्नलिखित युग्मों पर विचार कीजिए जहाँ मध्यकाल में उनका प्रभाव था:','{"list_1": ["1. Khokhars", "2. Langahs and Arghuns", "3. Cheros", "4. Bhils"], "list_1_hi": ["1. खोखर", "2. लंगाह और अरग़ून", "3. चेरो", "4. भील"], "list_2": ["Punjab", "Multan and Sind", "Bihar and Jharkhand", "Western and central India"], "list_2_hi": ["पंजाब", "मुल्तान और सिंध", "बिहार और झारखंड", "पश्चिमी और मध्य भारत"], "closing": "How many of the pairs given above are correctly matched?", "closing_hi": "उपर्युक्त में से कितने युग्म सही सुमेलित हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb,'[{"id": "a", "body": "Only one pair", "body_hi": "केवल एक युग्म", "isCorrect": false}, {"id": "b", "body": "Only two pairs", "body_hi": "केवल दो युग्म", "isCorrect": false}, {"id": "c", "body": "Only three pairs", "body_hi": "केवल तीन युग्म", "isCorrect": false}, {"id": "d", "body": "All four pairs", "body_hi": "सभी चार युग्म", "isCorrect": true}]'::jsonb,2,0.66,'All four pairs are correctly matched. The Khokhars were very influential in Punjab in the thirteenth and fourteenth centuries; the Langahs and Arghuns dominated Multan and Sind until the Mughals subdued them; Chero chiefdoms had emerged in present-day Bihar and Jharkhand by the twelfth century; and the Bhils spread across western and central India. Such tribal societies, many of them following customary laws rather than the varna order, ruled large areas and dealt with the Sultans and the Mughals as rivals, allies or subordinates.','चारों युग्म सही सुमेलित हैं। तेरहवीं और चौदहवीं सदी में पंजाब में खोखर बहुत प्रभावशाली थे; मुग़लों द्वारा अधीन किए जाने तक लंगाह और अरग़ून मुल्तान और सिंध पर हावी थे; बारहवीं सदी तक वर्तमान बिहार और झारखंड में चेरो सरदारियाँ उभर चुकी थीं; और भील पश्चिमी और मध्य भारत में फैले थे। ऐसे जनजातीय समाज, जिनमें से कई वर्ण व्यवस्था के बजाय परंपरागत नियमों को मानते थे, बड़े क्षेत्रों पर शासन करते थे और सुल्तानों तथा मुग़लों से प्रतिद्वंद्वी, सहयोगी या अधीनस्थ के रूप में व्यवहार करते थे।','l1-his-tribal-communities-regions-pairs','original_pattern_matched','NCERT Class VII, History -- Our Pasts II, Chapter 7 (Tribes, Nomads and Settled Communities).','draft'),
('upsc','History','Medieval','mcq','medium','Al-Biruni''s account of Indian society, written in the eleventh century, is said to have been shaped by the sources he relied on. Which one of the following best describes this?','ग्यारहवीं सदी में लिखे गए अल-बिरूनी के भारतीय समाज के वृत्तांत के बारे में कहा जाता है कि वह उसके स्रोतों से प्रभावित था। निम्नलिखित में से कौन-सा कथन इसका सबसे अच्छा वर्णन करता है?','{"craft": "inference"}'::jsonb,'[{"id": "a", "body": "He drew mainly on Brahmanical Sanskrit texts, so his account of caste followed them", "body_hi": "वह मुख्य रूप से ब्राह्मणवादी संस्कृत ग्रंथों पर निर्भर था, इसलिए जाति का उसका वर्णन उन्हीं के अनुसार था", "isCorrect": true}, {"id": "b", "body": "He relied on interviews with peasants and artisans, so he described only village life", "body_hi": "वह किसानों और कारीगरों से बातचीत पर निर्भर था, इसलिए उसने केवल ग्रामीण जीवन का वर्णन किया", "isCorrect": false}, {"id": "c", "body": "He used Chinese pilgrims'' accounts, since he could not read any Indian language", "body_hi": "उसने चीनी तीर्थयात्रियों के वृत्तांतों का उपयोग किया, क्योंकि वह कोई भारतीय भाषा नहीं पढ़ सकता था", "isCorrect": false}, {"id": "d", "body": "He copied Persian court chronicles, which described only the deeds of kings", "body_hi": "उसने फ़ारसी दरबारी इतिहासों की नक़ल की, जिनमें केवल राजाओं के कार्यों का वर्णन था", "isCorrect": false}]'::jsonb,2,0.66,'Al-Biruni, who learnt Sanskrit, depended almost exclusively on the works of brahmanas, often citing the Vedas, the Puranas, the Bhagavad Gita and the Manusmriti; his account of the caste system therefore followed the normative texts, which set out the rules from the brahmanas'' point of view. In real life the system was less rigid -- groups outside the varna order were drawn into the economy as labourers. He himself listed the barriers to understanding India: language, differences in religious beliefs and practices, and the self-absorption and insularity of the local people.','संस्कृत सीखने वाला अल-बिरूनी लगभग पूरी तरह ब्राह्मणों की रचनाओं पर निर्भर था, और प्रायः वेदों, पुराणों, भगवद्गीता और मनुस्मृति को उद्धृत करता था; इसलिए जाति व्यवस्था का उसका वर्णन उन मानक ग्रंथों के अनुसार था, जो ब्राह्मणों के दृष्टिकोण से नियम निर्धारित करते थे। वास्तविक जीवन में व्यवस्था इतनी कठोर नहीं थी -- वर्ण व्यवस्था से बाहर के समूह मज़दूरों के रूप में अर्थव्यवस्था में शामिल थे। उसने स्वयं भारत को समझने की बाधाएँ गिनाईं: भाषा, धार्मिक विश्वासों और प्रथाओं में अंतर, और स्थानीय लोगों का आत्मकेंद्रित और अलग-थलग रहना।','l1-his-albiruni-sources-caste','original_pattern_matched','NCERT Class XII, History -- Themes in Indian History, Part II, Chapter 5 (Through the Eyes of Travellers).','draft'),
('upsc','History','Medieval','mcq','medium','François Bernier, who travelled in Mughal India in the seventeenth century, argued that a fundamental difference between Mughal India and Europe was','सत्रहवीं सदी में मुग़ल भारत की यात्रा करने वाले फ़्रांस्वा बर्नियर ने तर्क दिया कि मुग़ल भारत और यूरोप के बीच एक मूलभूत अंतर था','{"craft": "inference"}'::jsonb,'[{"id": "a", "body": "the use of paper money in India, while Europe still relied on gold and silver coins", "body_hi": "भारत में काग़ज़ी मुद्रा का प्रयोग, जबकि यूरोप अब भी सोने-चाँदी के सिक्कों पर निर्भर था", "isCorrect": false}, {"id": "b", "body": "the absence of towns in India, where almost everyone lived in small villages", "body_hi": "भारत में नगरों का अभाव, जहाँ लगभग सभी लोग छोटे गाँवों में रहते थे", "isCorrect": false}, {"id": "c", "body": "the election of Indian rulers by assemblies of nobles, unlike Europe''s hereditary kings", "body_hi": "यूरोप के वंशानुगत राजाओं के विपरीत, भारतीय शासकों का अमीरों की सभाओं द्वारा चुनाव", "isCorrect": false}, {"id": "d", "body": "the lack of private property in land, which he thought belonged wholly to the emperor", "body_hi": "भूमि में निजी स्वामित्व का अभाव, जिसे वह पूरी तरह सम्राट की संपत्ति मानता था", "isCorrect": true}]'::jsonb,2,0.66,'Bernier believed that the crown owned all the land, so landholders could not pass it on to their children and had no reason to invest in it; this, he argued, ruined agriculture and produced a uniformly impoverished peasantry, ruled over by a small, rich elite. His comparisons, written to show the superiority of Europe, fed later ideas of ''oriental despotism''. But Mughal sources do not suggest that the state was the sole owner of land, and Bernier himself described large, busy towns -- historians therefore read his account critically.','बर्नियर मानता था कि सारी भूमि राजा की है, इसलिए भूमिधारक उसे अपने बच्चों को नहीं दे सकते थे और उसमें निवेश का कोई कारण नहीं था; उसके अनुसार इसने खेती को बर्बाद किया और एक समान रूप से ग़रीब किसान वर्ग पैदा किया, जिस पर एक छोटा धनी अभिजात वर्ग शासन करता था। यूरोप की श्रेष्ठता दिखाने के लिए लिखी गई उसकी तुलनाओं ने बाद में ''प्राच्य निरंकुशता'' (oriental despotism) के विचारों को बढ़ावा दिया। पर मुग़ल स्रोत यह नहीं बताते कि राज्य भूमि का एकमात्र स्वामी था, और बर्नियर ने स्वयं बड़े, व्यस्त नगरों का वर्णन किया -- इसलिए इतिहासकार उसके वृत्तांत को आलोचनात्मक दृष्टि से पढ़ते हैं।','l1-his-bernier-land-ownership','original_pattern_matched','NCERT Class XII, History -- Themes in Indian History, Part II, Chapter 5 (Through the Eyes of Travellers).','draft'),
('upsc','History','Medieval','mcq','medium','The Ain-i Akbari is a major source for the agrarian history of Mughal India. Which one of the following is a limitation that historians note in using it?','आइन-ए-अकबरी मुग़ल भारत के कृषि इतिहास का एक प्रमुख स्रोत है। निम्नलिखित में से कौन-सी एक सीमा है जिसे इसका उपयोग करते समय इतिहासकार रेखांकित करते हैं?','{"craft": "inference"}'::jsonb,'[{"id": "a", "body": "It was written by a European traveller who did not understand Indian conditions", "body_hi": "इसे एक यूरोपीय यात्री ने लिखा, जो भारतीय परिस्थितियों को नहीं समझता था", "isCorrect": false}, {"id": "b", "body": "Its numbers are uneven: fuller for some provinces and periods than for others", "body_hi": "इसके आँकड़े असमान हैं: कुछ प्रांतों और कालों के लिए दूसरों से अधिक विस्तृत", "isCorrect": true}, {"id": "c", "body": "It describes only court ceremonies and says nothing about land revenue", "body_hi": "इसमें केवल दरबारी समारोहों का वर्णन है और भू-राजस्व के बारे में कुछ नहीं", "isCorrect": false}, {"id": "d", "body": "It was compiled under Aurangzeb, long after the reign it describes", "body_hi": "इसे औरंगज़ेब के समय, उस शासनकाल के बहुत बाद संकलित किया गया जिसका यह वर्णन करता है", "isCorrect": false}]'::jsonb,2,0.66,'The Ain, completed in 1598 after five revisions as the third book of the Akbar Nama, is a mine of information on the organisation of the court, the army, revenue and the provinces. But historians note its problems: there are errors in totalling; the numerical data were not collected uniformly -- detailed figures on the caste composition of zamindars exist for many provinces but not for Bengal and Orissa -- and prices and wages are recorded mainly for the region around Agra. It also reflects the imperial point of view, so it is read alongside other sources, such as the records of villages and of the East India Company.','पाँच संशोधनों के बाद 1598 में अकबरनामा के तीसरे खंड के रूप में पूरी हुई आइन दरबार, सेना, राजस्व और प्रांतों के संगठन की जानकारी का भंडार है। पर इतिहासकार इसकी समस्याएँ बताते हैं: जोड़ में त्रुटियाँ हैं; आँकड़े एक समान रूप से नहीं जुटाए गए -- ज़मींदारों की जातिगत संरचना के विस्तृत आँकड़े कई प्रांतों के लिए हैं पर बंगाल और उड़ीसा के लिए नहीं -- और क़ीमतें तथा मज़दूरी मुख्यतः आगरा के आसपास के क्षेत्र के लिए दर्ज हैं। यह शाही दृष्टिकोण भी प्रस्तुत करती है, इसलिए इसे गाँवों और ईस्ट इंडिया कंपनी के अभिलेखों जैसे अन्य स्रोतों के साथ पढ़ा जाता है।','l1-his-ain-i-akbari-limits','original_pattern_matched','NCERT Class XII, History -- Themes in Indian History, Part II, Chapter 8 (Peasants, Zamindars and the State).','draft'),
('upsc','History','Medieval','statement_based','medium','Consider the following statements about the peasants and land of Mughal India, as described in the sources of the period:','उस काल के स्रोतों में वर्णित मुग़ल भारत के किसानों और भूमि के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Khud-kashta peasants were residents of the village in which they held their lands.", "Pahi-kashta peasants were those who held land in their own village by hereditary right.", "In Akbar''s classification of land, polaj was land left fallow for five years or more."], "statements_hi": ["ख़ुद-काश्त किसान उसी गाँव के निवासी थे जिसमें उनकी ज़मीन थी।", "पाही-काश्त किसान वे थे जो अपने ही गाँव में वंशानुगत अधिकार से ज़मीन रखते थे।", "अकबर के भूमि-वर्गीकरण में पोलज वह भूमि थी जो पाँच वर्ष या अधिक समय तक परती छोड़ी गई हो।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct. Statement 2 is wrong: the pahi-kashta were non-resident cultivators who belonged to some other village but cultivated lands elsewhere on a contractual basis -- some by choice, when terms were better, some forced by famine or economic distress. Statement 3 is wrong: polaj was land cultivated every year for each crop in succession and never left fallow; parauti was left out of cultivation for a time to recover, chachar lay fallow for three or four years, and banjar was uncultivated for five years and more.','केवल कथन 1 सही है। कथन 2 गलत है: पाही-काश्त ग़ैर-निवासी किसान थे, जो किसी दूसरे गाँव के होते हुए अन्यत्र अनुबंध के आधार पर खेती करते थे -- कुछ अपनी इच्छा से, जब शर्तें बेहतर हों, और कुछ अकाल या आर्थिक संकट से मजबूर होकर। कथन 3 गलत है: पोलज वह भूमि थी जिस पर हर वर्ष एक के बाद एक फ़सल उगाई जाती थी और जो कभी परती नहीं छोड़ी जाती थी; परौती को कुछ समय के लिए खेती से बाहर छोड़ा जाता था ताकि वह फिर उपजाऊ हो, चचर तीन-चार वर्ष परती रहती थी, और बंजर पाँच वर्ष या अधिक समय तक बिना खेती के रहती थी।','l1-his-khud-kashta-polaj','original_pattern_matched','NCERT Class XII, History -- Themes in Indian History, Part II, Chapter 8 (Peasants, Zamindars and the State).','draft'),
('upsc','History','Medieval','statement_based','medium','Consider the following statements about the village panchayat in Mughal India:','मुग़ल भारत में ग्राम पंचायत के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["It was headed by a muqaddam or mandal, chosen through the consensus of the village elders.", "It could levy fines and inflict punishments, such as expelling a person from the community.", "Caste (jati) panchayats had no role in the village, and all disputes went to the village panchayat."], "statements_hi": ["इसका मुखिया मुक़द्दम या मंडल होता था, जिसे गाँव के बुज़ुर्गों की सहमति से चुना जाता था।", "यह जुर्माना लगा सकती थी और दंड दे सकती थी, जैसे किसी व्यक्ति को समुदाय से बाहर निकालना।", "जाति पंचायतों की गाँव में कोई भूमिका नहीं थी, और सभी विवाद ग्राम पंचायत के पास जाते थे।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. The panchayat, an assembly of elders with hereditary rights in the village, was headed by a headman whose choice by the elders had to be ratified by the zamindar; it kept the village accounts with the help of the patwari, and could expel a person from the community -- a drastic punishment that cut him off from his caste and profession. Statement 3 is wrong: each jati in the village had its own panchayat, which wielded considerable power -- in Rajasthan, for instance, jati panchayats arbitrated civil disputes, mediated in contested claims to land and decided whether marriages had been made according to the norms.','कथन 1 और 2 सही हैं। गाँव में वंशानुगत अधिकार रखने वाले बुज़ुर्गों की सभा, पंचायत, का मुखिया एक प्रधान होता था, जिसके बुज़ुर्गों द्वारा चुनाव की पुष्टि ज़मींदार करता था; वह पटवारी की मदद से गाँव का हिसाब रखती थी, और किसी व्यक्ति को समुदाय से निकाल सकती थी -- एक कठोर दंड जो उसे उसकी जाति और व्यवसाय से काट देता था। कथन 3 गलत है: गाँव की हर जाति की अपनी पंचायत होती थी, जिसकी काफ़ी शक्ति थी -- उदाहरण के लिए राजस्थान में जाति पंचायतें दीवानी विवादों में मध्यस्थता करती थीं, भूमि के विवादित दावों को सुलझाती थीं और तय करती थीं कि विवाह मानदंडों के अनुसार हुए या नहीं।','l1-his-village-panchayat-muqaddam','original_pattern_matched','NCERT Class XII, History -- Themes in Indian History, Part II, Chapter 8 (Peasants, Zamindars and the State).','draft'),
('upsc','History','Medieval','statement_based','medium','Consider the following statements about Vijayanagara and its ruins at Hampi:','विजयनगर और हम्पी के उसके खंडहरों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The ruins were brought to light in 1800 by Colin Mackenzie, an engineer and antiquarian in the service of the East India Company.", "The name ''Lotus Mahal'' was given to one of its buildings by British travellers in the nineteenth century.", "The Mahanavami dibba, a massive platform, is associated with the Mahanavami festival held in September and October."], "statements_hi": ["इन खंडहरों को 1800 में ईस्ट इंडिया कंपनी की सेवा में रहे इंजीनियर और पुरावेत्ता कॉलिन मैकेंज़ी ने प्रकाश में लाया।", "''लोटस महल'' नाम इसकी एक इमारत को उन्नीसवीं सदी में ब्रिटिश यात्रियों ने दिया।", "विशाल चबूतरा, महानवमी डिब्बा, सितंबर-अक्टूबर में मनाए जाने वाले महानवमी पर्व से जुड़ा है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. Mackenzie, who became the first Surveyor General of India, prepared the first survey map of the site, drawing on the memories of priests of the Virupaksha temple and the shrine of Pampadevi. Many building names are later labels: ''Lotus Mahal'' was coined by British travellers, and historians are not sure what the building was used for. The rituals associated with the Mahanavami dibba probably coincided with Mahanavami (the ''great ninth day'') of the ten-day autumn festival known as Dussehra in the north, Durga Puja in Bengal and Navaratri or Mahanavami in the peninsula.','तीनों कथन सही हैं। भारत के पहले सर्वेयर जनरल बने मैकेंज़ी ने विरूपाक्ष मंदिर और पंपादेवी के देवस्थान के पुजारियों की स्मृतियों के सहारे इस स्थल का पहला सर्वेक्षण मानचित्र तैयार किया। कई इमारतों के नाम बाद में दिए गए हैं: ''लोटस महल'' नाम ब्रिटिश यात्रियों ने गढ़ा, और इतिहासकार निश्चित नहीं हैं कि उस इमारत का उपयोग किसलिए होता था। महानवमी डिब्बा से जुड़े अनुष्ठान संभवतः दस दिन के उस शरद पर्व की महानवमी (''महान नौवाँ दिन'') के साथ होते थे, जिसे उत्तर में दशहरा, बंगाल में दुर्गा पूजा और प्रायद्वीप में नवरात्रि या महानवमी कहते हैं।','l1-his-hampi-mackenzie-mahanavami','original_pattern_matched','NCERT Class XII, History -- Themes in Indian History, Part II, Chapter 7 (An Imperial Capital: Vijayanagara).','draft'),
('upsc','History','Medieval','statement_based','medium','Consider the following statements about the Alvars and Nayanars:','आलवारों और नयनारों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The Nalayira Divyaprabandham, an anthology of the compositions of the Alvars, was described as the ''Tamil Veda'', as significant as the four Vedas.", "Karaikkal Ammaiyar, a woman devotee of Shiva, adopted the path of extreme asceticism, and her compositions were preserved within the Nayanar tradition.", "Andal was a woman Nayanar, whose compositions were dedicated to Shiva."], "statements_hi": ["आलवारों की रचनाओं के संकलन नालायिर दिव्यप्रबंधम को ''तमिल वेद'' कहा गया, जो चारों वेदों जितना ही महत्वपूर्ण है।", "शिव की भक्त करइक्काल अम्मैयार ने कठोर तपस्या का मार्ग अपनाया, और उनकी रचनाएँ नयनार परंपरा में सुरक्षित रखी गईं।", "आंडाल एक नयनार भक्त महिला थीं, जिनकी रचनाएँ शिव को समर्पित थीं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. By the tenth century the compositions of the twelve Alvars, devotees of Vishnu, had been compiled in the Nalayira Divyaprabandham (''Four Thousand Sacred Compositions''), and the poems of the Nayanars, devotees of Shiva, in the Tevaram. Statement 3 is wrong: Andal was a woman Alvar, a devotee of Vishnu, whose compositions, in which she saw herself as the beloved of Vishnu, were widely sung; the presence of women poets such as Andal and Karaikkal Ammaiyar challenged patriarchal norms.','कथन 1 और 2 सही हैं। दसवीं सदी तक विष्णु के भक्त बारह आलवारों की रचनाएँ नालायिर दिव्यप्रबंधम (''चार हज़ार पवित्र रचनाएँ'') में, और शिव के भक्त नयनारों की कविताएँ तेवारम में संकलित हो चुकी थीं। कथन 3 गलत है: आंडाल विष्णु की भक्त एक महिला आलवार थीं, जिनकी रचनाएँ, जिनमें वे स्वयं को विष्णु की प्रिया मानती थीं, व्यापक रूप से गाई जाती थीं; आंडाल और करइक्काल अम्मैयार जैसी कवयित्रियों की उपस्थिति ने पितृसत्तात्मक मानदंडों को चुनौती दी।','l1-his-alvars-nayanars-women','original_pattern_matched','NCERT Class XII, History -- Themes in Indian History, Part II, Chapter 6 (Bhakti-Sufi Traditions).','draft'),
('upsc','History','Medieval','statement_based','medium','Consider the following statements about the Mughal court:','मुग़ल दरबार के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["In the jharokha darshan, the emperor appeared at a balcony facing east at sunrise, to be seen by the people gathered below.", "The kornish was a salutation in which the courtier embraced the emperor as an equal.", "The Mughal chronicles were written mainly in Turki, the mother tongue of the dynasty."], "statements_hi": ["झरोखा दर्शन में सम्राट सूर्योदय के समय पूर्व की ओर खुलने वाले झरोखे में प्रकट होते थे, ताकि नीचे जमा लोग उन्हें देख सकें।", "कोर्निश एक अभिवादन था जिसमें दरबारी सम्राट को बराबरी से गले लगाता था।", "मुग़ल इतिहास मुख्य रूप से राजवंश की मातृभाषा तुर्की में लिखे गए।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct: introduced by Akbar, the jharokha darshan, at the start of the emperor''s day, was meant to broaden the acceptance of imperial authority as part of popular faith. Statement 2 is wrong: the kornish was a ceremonial salutation in which the courtier placed the palm of his right hand against his forehead and bent his head -- the deeper the prostration, the higher the status of the person before whom it was made. Statement 3 is wrong: Babur wrote his memoirs in Turki, but Akbar made Persian the leading language of the court, and chronicles such as the Akbar Nama and the Badshah Nama were written in Persian.','केवल कथन 1 सही है: अकबर द्वारा शुरू किया गया झरोखा दर्शन, सम्राट के दिन की शुरुआत में, शाही सत्ता को लोकआस्था के अंग के रूप में व्यापक स्वीकृति दिलाने के लिए था। कथन 2 गलत है: कोर्निश एक औपचारिक अभिवादन था जिसमें दरबारी दाहिने हाथ की हथेली माथे पर रखकर सिर झुकाता था -- जितना गहरा झुकना, उतनी ऊँची उस व्यक्ति की हैसियत जिसके सामने झुका जाए। कथन 3 गलत है: बाबर ने अपने संस्मरण तुर्की में लिखे, पर अकबर ने फ़ारसी को दरबार की प्रमुख भाषा बनाया, और अकबरनामा तथा बादशाहनामा जैसे इतिहास फ़ारसी में लिखे गए।','l1-his-mughal-court-jharokha-kornish','original_pattern_matched','NCERT Class XII, History -- Themes in Indian History, Part II, Chapter 9 (Kings and Chronicles).','draft'),
('upsc','History','Medieval','match_the_following','medium','Consider the following pairs relating to the making of regional cultures:','क्षेत्रीय संस्कृतियों के निर्माण से संबंधित निम्नलिखित युग्मों पर विचार कीजिए:','{"list_1": ["1. Manipravalam", "2. Mahodayapuram", "3. Jagannatha cult", "4. Bengali"], "list_1_hi": ["1. मणिप्रवालम", "2. महोदयपुरम", "3. जगन्नाथ संप्रदाय", "4. बांग्ला"], "list_2": ["A style of writing that mixed Sanskrit with the regional language of Kerala", "Capital of the Chera kingdom established in the ninth century", "Centred on Puri, where Anantavarman of the Eastern Gangas built a temple in the twelfth century", "A language derived from Sanskrit that absorbed words from tribal languages, Persian and European languages"], "list_2_hi": ["संस्कृत को केरल की क्षेत्रीय भाषा के साथ मिलाकर लिखने की शैली", "नौवीं सदी में स्थापित चेर राज्य की राजधानी", "पुरी पर केंद्रित, जहाँ बारहवीं सदी में पूर्वी गंग वंश के अनंतवर्मन ने मंदिर बनवाया", "संस्कृत से निकली भाषा, जिसने जनजातीय भाषाओं, फ़ारसी और यूरोपीय भाषाओं के शब्द अपनाए"], "closing": "How many of the pairs given above are correctly matched?", "closing_hi": "उपर्युक्त में से कितने युग्म सही सुमेलित हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb,'[{"id": "a", "body": "Only one pair", "body_hi": "केवल एक युग्म", "isCorrect": false}, {"id": "b", "body": "Only two pairs", "body_hi": "केवल दो युग्म", "isCorrect": false}, {"id": "c", "body": "Only three pairs", "body_hi": "केवल तीन युग्म", "isCorrect": false}, {"id": "d", "body": "All four pairs", "body_hi": "सभी चार युग्म", "isCorrect": true}]'::jsonb,2,0.66,'All four pairs are correctly matched. The Chera kingdom of Mahodayapuram, in present-day Kerala, introduced Malayalam in its inscriptions while drawing on Sanskrit traditions; the fourteenth-century Lilatilakam, on grammar and poetics, was composed in manipravalam, ''diamonds and corals'', the two languages. In Odisha, Anantavarman''s temple to Purushottama Jagannatha at Puri, and later rulers'' dedication of their kingdom to the deity, made the cult central to regional identity; and Bengali grew from a Sanskrit-derived language into one shaped by many contacts.','चारों युग्म सही सुमेलित हैं। वर्तमान केरल में महोदयपुरम के चेर राज्य ने संस्कृत परंपराओं को अपनाते हुए अपने अभिलेखों में मलयालम का प्रयोग शुरू किया; व्याकरण और काव्यशास्त्र पर चौदहवीं सदी का लीलातिलकम मणिप्रवालम -- ''हीरे और मूँगे'', यानी दोनों भाषाओं -- में रचा गया। ओडिशा में पुरी में पुरुषोत्तम जगन्नाथ के लिए अनंतवर्मन के मंदिर, और बाद के शासकों द्वारा अपना राज्य देवता को समर्पित करने, ने इस संप्रदाय को क्षेत्रीय पहचान का केंद्र बना दिया; और बांग्ला संस्कृत से निकली भाषा से बढ़कर अनेक संपर्कों से गढ़ी गई भाषा बनी।','l1-his-regional-cultures-pairs','original_pattern_matched','NCERT Class VII, History -- Our Pasts II, Chapter 9 (The Making of Regional Cultures).','draft'),
('upsc','History','Medieval','mcq','hard','Abu''l Fazl described Mughal kingship in terms of farr-i izadi. What did this idea convey?','अबुल फ़ज़्ल ने मुग़ल बादशाहत का वर्णन फ़र्र-ए-इज़ादी के रूप में किया। यह विचार क्या बताता था?','{"craft": "inference"}'::jsonb,'[{"id": "a", "body": "The king was elected by the nobles and could be removed if he lost their confidence", "body_hi": "राजा अमीरों द्वारा चुना जाता था और उनका विश्वास खोने पर हटाया जा सकता था", "isCorrect": false}, {"id": "b", "body": "The king''s authority rested entirely on the approval of the ulama, who interpreted the sharia", "body_hi": "राजा का अधिकार पूरी तरह शरिया की व्याख्या करने वाले उलेमा की स्वीकृति पर टिका था", "isCorrect": false}, {"id": "c", "body": "The emperor was bound to share power equally with the Rajput rulers who served him", "body_hi": "सम्राट अपनी सेवा करने वाले राजपूत शासकों के साथ सत्ता बराबर बाँटने को बाध्य था", "isCorrect": false}, {"id": "d", "body": "Sovereignty was a light emanating from God, received by the king and passed down the dynasty", "body_hi": "संप्रभुता ईश्वर से निकलने वाला प्रकाश थी, जिसे राजा ग्रहण करता था और जो वंश में आगे बढ़ता था", "isCorrect": true}]'::jsonb,2,0.66,'Abu''l Fazl placed Mughal kingship at the top of a hierarchy of objects receiving light emanating from God (farr-i izadi), an idea drawn from Iranian mystical thought: the divine light was transmitted to the king, who then became the source of spiritual guidance for his subjects. Court painters showed it through the halo around the emperor''s head. The idea raised the emperor above every group in the empire, including the ulama, rather than making his authority depend on them.','अबुल फ़ज़्ल ने मुग़ल बादशाहत को ईश्वर से निकलने वाला प्रकाश (फ़र्र-ए-इज़ादी) ग्रहण करने वाली वस्तुओं के पदानुक्रम में सबसे ऊपर रखा, जो ईरानी रहस्यवादी चिंतन से लिया गया विचार था: दिव्य प्रकाश राजा तक पहुँचता था, जो फिर अपनी प्रजा के लिए आध्यात्मिक मार्गदर्शन का स्रोत बनता था। दरबारी चित्रकारों ने इसे सम्राट के सिर के चारों ओर प्रभामंडल से दिखाया। इस विचार ने सम्राट को साम्राज्य के हर समूह से ऊपर रखा, उलेमा सहित, बजाय इसके कि उसका अधिकार उन पर निर्भर हो।','l1-his-farr-i-izadi-kingship','original_pattern_matched','NCERT Class XII, History -- Themes in Indian History, Part II, Chapter 9 (Kings and Chronicles).','draft'),
('upsc','History','Medieval','statement_based','hard','Consider the following statements about Ibn Battuta''s account of India in the fourteenth century:','चौदहवीं सदी में इब्न बतूता के भारत-वृत्तांत के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["He described the coconut and the paan in detail, as things his readers at home had never seen.", "He reported that letters took about fifty days to reach Delhi from Sind, because there was no organised postal service.", "He found the cities of India thinly populated, with poorly stocked markets."], "statements_hi": ["उसने नारियल और पान का विस्तार से वर्णन किया, क्योंकि उसके देश के पाठकों ने ये कभी नहीं देखे थे।", "उसने बताया कि कोई संगठित डाक व्यवस्था न होने के कारण सिंध से दिल्ली तक पत्र पहुँचने में लगभग पचास दिन लगते थे।", "उसने भारत के नगरों को विरल आबादी वाला और बाज़ारों को कम सामान वाला पाया।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct: to make the unfamiliar vivid, he compared the coconut to a man''s head and described the paan carefully. Statement 2 is wrong: he was struck by the efficient postal system, with a horse post (uluq) and a foot post (dawa) -- while the journey from Sind to Delhi took fifty days, news reports reached the Sultan through the postal system in just five. Statement 3 is wrong: he found the cities densely populated and prosperous, with crowded streets and bright, colourful markets stocked with a wide variety of goods; Delhi was a vast city, and Daulatabad was no smaller.','केवल कथन 1 सही है: अपरिचित को सजीव बनाने के लिए उसने नारियल की तुलना मनुष्य के सिर से की और पान का सावधानी से वर्णन किया। कथन 2 गलत है: वह कुशल डाक व्यवस्था से प्रभावित हुआ, जिसमें घोड़ा डाक (उलुक़) और पैदल डाक (दावा) थी -- जहाँ सिंध से दिल्ली की यात्रा में पचास दिन लगते थे, वहीं डाक व्यवस्था से समाचार सुल्तान तक केवल पाँच दिन में पहुँचते थे। कथन 3 गलत है: उसने नगरों को घनी आबादी वाला और समृद्ध पाया, भीड़-भरी गलियों और विविध वस्तुओं से भरे चमकीले, रंगीन बाज़ारों के साथ; दिल्ली एक विशाल नगर था, और दौलताबाद उससे छोटा नहीं था।','l1-his-ibn-battuta-coconut-post','original_pattern_matched','NCERT Class XII, History -- Themes in Indian History, Part II, Chapter 5 (Through the Eyes of Travellers).','draft'),
('upsc','History','Architecture','mcq','easy','The temples built in Bengal from the late fifteenth century, such as those of Bishnupur, are best known for','पंद्रहवीं सदी के अंत से बंगाल में बने मंदिर, जैसे बिष्णुपुर के मंदिर, किस बात के लिए सबसे अधिक जाने जाते हैं?','{"craft": "precision"}'::jsonb,'[{"id": "a", "body": "white marble inlaid with semi-precious stones, in the style of the Mughal tombs", "body_hi": "मुग़ल मक़बरों की शैली में अर्ध-कीमती पत्थरों से जड़ा सफ़ेद संगमरमर", "isCorrect": false}, {"id": "b", "body": "being cut out of a single rock, from the top downwards, like the Kailasa temple", "body_hi": "कैलाश मंदिर की तरह एक ही चट्टान को ऊपर से नीचे की ओर काटकर बनाया जाना", "isCorrect": false}, {"id": "c", "body": "brick and terracotta, with roofs copying the thatched huts of the region", "body_hi": "ईंट और पकी मिट्टी (टेराकोटा), और क्षेत्र की छप्पर वाली झोपड़ियों की नक़ल करती छतें", "isCorrect": true}, {"id": "d", "body": "towering gopurams over the gateways, like those of the temples of Tamil Nadu", "body_hi": "तमिलनाडु के मंदिरों की तरह प्रवेशद्वारों पर ऊँचे गोपुरम", "isCorrect": false}]'::jsonb,2,0.66,'From the late fifteenth century, individuals and groups -- many of them from social groups whose status was rising -- built temples in Bengal of brick and terracotta. They copied the double-roofed (dochala) or four-roofed (chauchala) structure of the region''s thatched huts, and in the more complex four-roofed form, as at Bishnupur in Bankura district, a small tower rose from the roof. Their walls were decorated with ornamental tiles or terracotta tablets showing scenes of everyday life as well as religious stories.','पंद्रहवीं सदी के अंत से बंगाल में व्यक्तियों और समूहों ने -- जिनमें से कई उभरती हैसियत वाले सामाजिक समूहों से थे -- ईंट और पकी मिट्टी के मंदिर बनाए। उन्होंने क्षेत्र की छप्पर वाली झोपड़ियों की दो छत (दोचाला) या चार छत (चौचाला) वाली संरचना की नक़ल की, और अधिक जटिल चार छत वाले रूप में, जैसे बाँकुड़ा ज़िले के बिष्णुपुर में, छत से एक छोटा शिखर उठता था। उनकी दीवारें सजावटी टाइलों या पकी मिट्टी की पट्टिकाओं से सजी थीं, जिनमें दैनिक जीवन के दृश्य और धार्मिक कथाएँ दिखाई गई थीं।','l1-his-bengal-terracotta-temples','original_pattern_matched','NCERT Class VII, History -- Our Pasts II, Chapter 9 (The Making of Regional Cultures).','draft'),
('upsc','History','Architecture','statement_based','medium','Consider the following statements about how rulers in medieval India used buildings to show their power and their care for their subjects:','मध्यकालीन भारत में शासकों ने अपनी शक्ति और प्रजा के प्रति अपनी चिंता दिखाने के लिए इमारतों का उपयोग कैसे किया, इसके बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["In the early eleventh century, Rajendra I built a Shiva temple in his capital and filled it with prized statues seized from defeated rulers.", "Iltutmish won wide respect for building a large reservoir, the Hauz-i Sultani or ''King''s Reservoir'', just outside Delhi-i kuhna.", "Rulers built tanks and reservoirs only inside their palaces, for the use of the royal household."], "statements_hi": ["ग्यारहवीं सदी के आरंभ में राजेंद्र प्रथम ने अपनी राजधानी में एक शिव मंदिर बनवाया और उसे पराजित शासकों से छीनी गई बहुमूल्य मूर्तियों से भर दिया।", "दिल्ली-ए-कुहना के ठीक बाहर एक बड़ा जलाशय, हौज़-ए-सुल्तानी या ''राजा का जलाशय'', बनवाकर इल्तुतमिश ने व्यापक सम्मान पाया।", "शासक तालाब और जलाशय केवल अपने महलों के भीतर, शाही परिवार के उपयोग के लिए बनवाते थे।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. Since kings built temples to demonstrate their devotion and power, the temples of defeated kings were often targeted when they attacked one another -- Rajendra I''s statues were trophies of this kind. Rulers also built tanks and reservoirs, big and small, for the use of ordinary people; Iltutmish''s Hauz-i Sultani was one such work, and such public works helped a ruler''s claim to be just. Statement 3 is therefore wrong.','कथन 1 और 2 सही हैं। चूँकि राजा अपनी भक्ति और शक्ति दिखाने के लिए मंदिर बनवाते थे, इसलिए एक-दूसरे पर आक्रमण के समय पराजित राजाओं के मंदिरों को प्रायः निशाना बनाया जाता था -- राजेंद्र प्रथम की मूर्तियाँ ऐसी ही विजय-चिह्न थीं। शासक सामान्य लोगों के उपयोग के लिए छोटे-बड़े तालाब और जलाशय भी बनवाते थे; इल्तुतमिश का हौज़-ए-सुल्तानी ऐसा ही कार्य था, और ऐसे सार्वजनिक कार्य शासक के न्यायप्रिय होने के दावे को मज़बूत करते थे। इसलिए कथन 3 गलत है।','l1-his-rulers-buildings-hauz-i-sultani','original_pattern_matched','NCERT Class VII, History -- Our Pasts II, Chapter 5 (Rulers and Buildings).','draft'),
('upsc','History','Painting','statement_based','easy','Consider the following statements about painting at the Mughal court:','मुग़ल दरबार में चित्रकला के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Abu''l Fazl described painting as a ''magical art'', able to make inanimate objects look as if they possessed life.", "The orthodox ulama welcomed the depiction of human beings in painting."], "statements_hi": ["अबुल फ़ज़्ल ने चित्रकला को एक ''जादुई कला'' कहा, जो निर्जीव वस्तुओं को ऐसा दिखा सकती है मानो उनमें जीवन हो।", "रूढ़िवादी उलेमा ने चित्रकला में मनुष्यों के चित्रण का स्वागत किया।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": true}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct. Painters were given a high place at the court, and their paintings, which illustrated the chronicles, helped convey the emperor''s power and ideals. Statement 2 is wrong: the orthodox ulama invoked the Islamic prohibition of the portrayal of human beings; Akbar is said to have answered that a painter, drawing living things and finding he cannot give them life, is forced to think of God, the giver of life.','केवल कथन 1 सही है। दरबार में चित्रकारों को ऊँचा स्थान मिला, और इतिहास-ग्रंथों को चित्रित करने वाली उनकी कृतियाँ सम्राट की शक्ति और आदर्शों को व्यक्त करने में मदद करती थीं। कथन 2 गलत है: रूढ़िवादी उलेमा ने मनुष्यों के चित्रण पर इस्लामी निषेध का हवाला दिया; कहा जाता है कि अकबर ने उत्तर दिया कि सजीव वस्तुएँ बनाने वाला चित्रकार जब पाता है कि वह उनमें जीवन नहीं डाल सकता, तो उसे जीवनदाता ईश्वर के बारे में सोचना पड़ता है।','l1-his-mughal-painting-magical-art','original_pattern_matched','NCERT Class XII, History -- Themes in Indian History, Part II, Chapter 9 (Kings and Chronicles).','draft'),
('upsc','History','Painting','statement_based','medium','Consider the following statements about the manuscript painting traditions of early medieval India:','प्रारंभिक मध्यकालीन भारत की पांडुलिपि चित्रकला परंपराओं के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Pala manuscripts of eastern India, such as copies of the Ashtasahasrika Prajnaparamita, were illustrated on palm leaf.", "Western Indian manuscript painting is seen in Jaina texts such as the Kalpasutra.", "Both traditions grew up under the patronage of the Mughal emperors."], "statements_hi": ["पूर्वी भारत की पाल पांडुलिपियाँ, जैसे अष्टसाहस्रिका प्रज्ञापारमिता की प्रतियाँ, ताड़ के पत्तों पर चित्रित की गईं।", "पश्चिमी भारतीय पांडुलिपि चित्रकला कल्पसूत्र जैसे जैन ग्रंथों में दिखती है।", "दोनों परंपराएँ मुग़ल सम्राटों के संरक्षण में विकसित हुईं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. Buddhist monasteries under the Pala rulers of eastern India (about the eighth to the twelfth century) produced illustrated palm-leaf manuscripts, while in western India Jaina patrons commissioned illustrated texts such as the Kalpasutra, with figures in angular lines and bright colours, at first on palm leaf and later on paper. Statement 3 is wrong: both traditions are centuries older than the Mughals, who arrived in the sixteenth century.','कथन 1 और 2 सही हैं। पूर्वी भारत के पाल शासकों (लगभग आठवीं से बारहवीं सदी) के समय बौद्ध विहारों में चित्रित ताड़पत्र पांडुलिपियाँ बनीं, जबकि पश्चिमी भारत में जैन संरक्षकों ने कल्पसूत्र जैसे चित्रित ग्रंथ बनवाए, जिनमें कोणीय रेखाओं और चटक रंगों में आकृतियाँ थीं, पहले ताड़पत्र पर और बाद में काग़ज़ पर। कथन 3 गलत है: दोनों परंपराएँ सोलहवीं सदी में आए मुग़लों से सदियों पुरानी हैं।','l1-his-pala-western-indian-manuscripts','original_pattern_matched','NCERT Class XII, Fine Art -- An Introduction to Indian Art, Part II, Chapter 1 (The Manuscript Painting Tradition).','draft'),
('upsc','History','Iconography','statement_based','easy','Consider the following statements about the great rock relief at Mamallapuram:','मामल्लपुरम की विशाल शिला-उत्कीर्ण कलाकृति (rock relief) के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Carved in the seventh century under the Pallavas, it has been interpreted as the descent of the Ganga or as Arjuna''s penance.", "It was carved on the inner wall of a brick temple built to house it."], "statements_hi": ["पल्लवों के समय सातवीं सदी में उकेरी गई इस कलाकृति को गंगावतरण या अर्जुन की तपस्या के रूप में समझा गया है।", "इसे इसके लिए बनाए गए एक ईंट के मंदिर की भीतरी दीवार पर उकेरा गया।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": true}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct. The relief teems with gods, sages, humans and animals converging on a natural cleft in the rock, which may have represented the river -- hence the two readings, the descent of the Ganga or Arjuna''s penance to win a weapon from Shiva. Statement 2 is wrong: it was carved in the open air on the face of huge boulders, one of the largest reliefs of its kind in the world.','केवल कथन 1 सही है। इस कलाकृति में देवता, ऋषि, मनुष्य और पशु चट्टान की एक प्राकृतिक दरार की ओर बढ़ते दिखते हैं, जो संभवतः नदी का प्रतीक थी -- इसीलिए इसकी दो व्याख्याएँ हैं, गंगावतरण या शिव से अस्त्र पाने के लिए अर्जुन की तपस्या। कथन 2 गलत है: इसे खुले में विशाल शिलाओं की सतह पर उकेरा गया, और यह अपनी तरह की संसार की सबसे बड़ी कलाकृतियों में से एक है।','l1-his-mamallapuram-relief','original_pattern_matched','NCERT Class XI, Fine Art -- An Introduction to Indian Art, Part I, Chapter 6 (Temple Architecture and Sculpture).','draft'),
('upsc','History','Iconography','statement_based','medium','Consider the following statements about early yaksha and yakshi images:','प्रारंभिक यक्ष और यक्षी प्रतिमाओं के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Monumental yaksha images, such as the one from Parkham near Mathura, were made around the third and second centuries BCE.", "Yaksha worship was popular before and after the coming of Buddhism, and yakshas were absorbed into Buddhism and Jainism.", "These images are usually standing figures, shown frontally, with a polished surface."], "statements_hi": ["मथुरा के निकट परखम से मिली प्रतिमा जैसी विशाल यक्ष प्रतिमाएँ लगभग तीसरी और दूसरी सदी ई.पू. में बनीं।", "यक्ष पूजा बौद्ध धर्म के आने से पहले और बाद में लोकप्रिय थी, और यक्ष बौद्ध तथा जैन धर्म में आत्मसात हो गए।", "ये प्रतिमाएँ प्रायः खड़ी हुई, सामने से दिखाई गई और चमकदार सतह वाली होती हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. Large statues of yakshas and yakshis have been found at Patna, Vidisha, Mathura and other places; they are mostly standing, with a polished surface and faces shown in full round with pronounced cheeks. Their worship, part of popular religion, was absorbed into Buddhism and Jainism -- yakshas and yakshis appear on stupa railings and gateways -- and the form of such images influenced later sculpture.','तीनों कथन सही हैं। यक्षों और यक्षियों की बड़ी प्रतिमाएँ पटना, विदिशा, मथुरा और अन्य स्थानों पर मिली हैं; वे अधिकतर खड़ी हैं, उनकी सतह चमकदार है, और चेहरे उभरे गालों के साथ पूरी गोलाई में दिखाए गए हैं। लोकधर्म का अंग, उनकी पूजा बौद्ध और जैन धर्म में आत्मसात हुई -- यक्ष और यक्षियाँ स्तूपों की वेदिकाओं और तोरणों पर दिखते हैं -- और ऐसी प्रतिमाओं के रूप ने बाद की मूर्तिकला को प्रभावित किया।','l1-his-yaksha-images-parkham','original_pattern_matched','NCERT Class XI, Fine Art -- An Introduction to Indian Art, Part I, Chapter 3 (Arts of the Mauryan Period).','draft'),
('upsc','History','Music & Dance','statement_based','easy','Consider the following statements about ragas in Hindustani music:','हिंदुस्तानी संगीत में रागों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The vadi is the most important note of a raga, and the samvadi the second most important.", "The aroha of a raga is its descending order of notes, and the avaroha its ascending order."], "statements_hi": ["वादी किसी राग का सबसे महत्वपूर्ण स्वर है, और संवादी दूसरा सबसे महत्वपूर्ण।", "किसी राग का आरोह उसके स्वरों का अवरोही क्रम है, और अवरोह उसका आरोही क्रम।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": true}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct: the vadi is the note most emphasised in a raga, and the samvadi, usually a fourth or a fifth away from it, comes next; together they help give the raga its character. Statement 2 reverses the terms: the aroha is the ascent and the avaroha the descent, and a raga may use different notes going up and coming down.','केवल कथन 1 सही है: वादी राग में सबसे अधिक बल पाने वाला स्वर है, और संवादी, जो प्रायः उससे चौथे या पाँचवें स्थान पर होता है, उसके बाद आता है; दोनों मिलकर राग को उसका स्वरूप देने में मदद करते हैं। कथन 2 शब्दों को उलट देता है: आरोह चढ़ाव है और अवरोह उतार, और कोई राग चढ़ते और उतरते समय अलग-अलग स्वरों का प्रयोग कर सकता है।','l1-his-raga-vadi-aroha','original_pattern_matched','NCERT music textbooks for Classes XI-XII (Hindustani music); Sangeet Natak Akademi.','draft'),
('upsc','History','Music & Dance','mcq','medium','A raga that uses five notes in both its ascent and its descent belongs to which jati (class)?','जो राग अपने आरोह और अवरोह, दोनों में पाँच स्वरों का प्रयोग करता है, वह किस जाति का है?','{"craft": "precision"}'::jsonb,'[{"id": "a", "body": "Shadava", "body_hi": "षाडव", "isCorrect": false}, {"id": "b", "body": "Sampurna", "body_hi": "संपूर्ण", "isCorrect": false}, {"id": "c", "body": "Vakra", "body_hi": "वक्र", "isCorrect": false}, {"id": "d", "body": "Audava", "body_hi": "औडव", "isCorrect": true}]'::jsonb,2,0.66,'Ragas are classed by the number of notes they use: audava (five), shadava (six) and sampurna (all seven); a raga may combine classes, using, say, six notes in the ascent and seven in the descent (shadava-sampurna). Bhupali, which leaves out ma and ni, is a well-known audava raga. Vakra describes a zigzag movement of notes, not their number.','रागों का वर्गीकरण उनके प्रयुक्त स्वरों की संख्या से होता है: औडव (पाँच), षाडव (छह) और संपूर्ण (सातों); कोई राग वर्गों को मिला भी सकता है, जैसे आरोह में छह और अवरोह में सात स्वर (षाडव-संपूर्ण)। म और नि को छोड़ने वाला भूपाली एक प्रसिद्ध औडव राग है। वक्र स्वरों की टेढ़ी-मेढ़ी चाल का वर्णन है, उनकी संख्या का नहीं।','l1-his-raga-jati-audava','original_pattern_matched','NCERT music textbooks for Classes XI-XII (Hindustani music); Sangeet Natak Akademi.','draft'),
('upsc','History','Music & Dance','statement_based','medium','Consider the following statements about some basic terms of Indian classical music:','भारतीय शास्त्रीय संगीत के कुछ मूल शब्दों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Vilambit, madhya and drut are the slow, medium and fast forms of laya, or tempo.", "The three registers of the saptak are mandra (low), madhya (middle) and tara (high).", "Indian music theory traditionally recognises twenty-two shrutis, or microtonal intervals, within an octave."], "statements_hi": ["विलंबित, मध्य और द्रुत लय (गति) के धीमे, मध्यम और तेज़ रूप हैं।", "सप्तक के तीन स्थान मंद्र (निचला), मध्य (बीच का) और तार (ऊँचा) हैं।", "भारतीय संगीतशास्त्र परंपरागत रूप से एक सप्तक में बाईस श्रुतियाँ, यानी सूक्ष्म स्वरांतर, मानता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "recall"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. A performance often moves from a slow (vilambit) to a medium (madhya) and then a fast (drut) tempo; the seven notes of the saptak are sung in a low, middle and high register; and theory, from the Natya Shastra onwards, divides the octave into twenty-two shrutis, from which the notes are chosen.','तीनों कथन सही हैं। प्रस्तुति प्रायः विलंबित से मध्य और फिर द्रुत लय में जाती है; सप्तक के सात स्वर निचले, बीच के और ऊँचे स्थान में गाए जाते हैं; और नाट्यशास्त्र से आगे का संगीतशास्त्र सप्तक को बाईस श्रुतियों में बाँटता है, जिनमें से स्वर चुने जाते हैं।','l1-his-laya-saptak-shruti','original_pattern_matched','NCERT music textbooks for Classes XI-XII (Hindustani music); Sangeet Natak Akademi.','draft'),
('upsc','History','Culture-Other','match_the_following','hard','Consider the following pairs of craft traditions and their descriptions:','शिल्प परंपराओं और उनके विवरणों के निम्नलिखित युग्मों पर विचार कीजिए:','{"list_1": ["1. Dhokra", "2. Blue pottery", "3. Sikki", "4. Papier-mache"], "list_1_hi": ["1. ढोकरा", "2. नीली मिट्टी के बर्तन (ब्लू पॉटरी)", "3. सिक्की", "4. पेपर-माशी"], "list_2": ["Metal casting by the lost-wax process, practised by tribal metalsmiths of eastern and central India", "Glazed pottery of Jaipur, coloured with cobalt oxide", "Golden grass woven into baskets, toys and figures in Bihar", "Objects of paper pulp, painted with fine designs, in Kashmir"], "list_2_hi": ["पूर्वी और मध्य भारत के जनजातीय धातुकारों द्वारा मोम-क्षय (lost-wax) विधि से धातु की ढलाई", "कोबाल्ट ऑक्साइड से रँगे जयपुर के चमकदार बर्तन", "बिहार में टोकरियाँ, खिलौने और आकृतियाँ बनाने के लिए बुनी जाने वाली सुनहरी घास", "कश्मीर में बारीक डिज़ाइनों से चित्रित काग़ज़ की लुगदी की वस्तुएँ"], "closing": "How many of the pairs given above are correctly matched?", "closing_hi": "उपर्युक्त में से कितने युग्म सही सुमेलित हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb,'[{"id": "a", "body": "Only one pair", "body_hi": "केवल एक युग्म", "isCorrect": false}, {"id": "b", "body": "Only two pairs", "body_hi": "केवल दो युग्म", "isCorrect": false}, {"id": "c", "body": "Only three pairs", "body_hi": "केवल तीन युग्म", "isCorrect": false}, {"id": "d", "body": "All four pairs", "body_hi": "सभी चार युग्म", "isCorrect": true}]'::jsonb,2,0.66,'All four pairs are correctly matched. Dhokra smiths of West Bengal, Odisha, Jharkhand and Chhattisgarh shape a wax model over a clay core, coat it with clay and melt the wax out before pouring in metal; Jaipur''s blue pottery, made from a quartz-based paste rather than clay, takes its colour from cobalt oxide; sikki grass from the Mithila region is dyed and coiled into boxes and figures; and Kashmiri papier-mache is built up from paper pulp and painted with floral designs.','चारों युग्म सही सुमेलित हैं। पश्चिम बंगाल, ओडिशा, झारखंड और छत्तीसगढ़ के ढोकरा कारीगर मिट्टी के ढाँचे पर मोम का नमूना बनाते हैं, उस पर मिट्टी चढ़ाकर मोम पिघलाकर निकालते हैं और फिर धातु डालते हैं; मिट्टी के बजाय क्वार्ट्ज़-आधारित लेप से बने जयपुर के नीले बर्तन अपना रंग कोबाल्ट ऑक्साइड से पाते हैं; मिथिला क्षेत्र की सिक्की घास रँगकर डिब्बों और आकृतियों में लपेटी जाती है; और कश्मीरी पेपर-माशी काग़ज़ की लुगदी से बनाकर फूलों के डिज़ाइनों से चित्रित की जाती है।','l1-his-craft-traditions-pairs','original_pattern_matched','NCERT Class XI, Heritage Crafts -- Living Craft Traditions of India; Development Commissioner (Handicrafts), Ministry of Textiles.','draft')
